      "arFull": "قْتُلُوْا یُوْسُفَ اَوِ اطْرَحُوْهُ اَرْضًا یَّخْلُ لَكُمْ وَجْهُ اَبِیْكُمْ وَتَكُوْنُوْا مِنْ بَعْدِهٖ قَوْمًا صٰلِحِیْنَ ۟",
