      "number": 32,
      "arFull": "قَالَتْ فَذٰلِكُنَّ الَّذِیْ لُمْتُنَّنِیْ فِیْهِ ؕ وَلَقَدْ رَاوَدْتُّهٗ عَنْ نَّفْسِهٖ فَاسْتَعْصَمَ ؕ وَلَىِٕنْ لَّمْ یَفْعَلْ مَاۤ اٰمُرُهٗ لَیُسْجَنَنَّ وَلَیَكُوْنًا مِّنَ الصّٰغِرِیْنَ ۟",
      "ur": "اس وقت عزیز مصر کی بیوی نے کہا، یہی ہے جن کے بارے میں تم مجھے طعنے دے رہی تھیں[1] ، میں نے ہر چند اس سے اپنا مطلب حاصل کرنا چاہا لیکن یہ بال بال بچا رہا، اور جو کچھ میں اس سے کہہ رہی ہوں اگر یہ نہ کرے گا تو یقیناً یہ قید کر دیا جائے گا اور بیشک یہ بہت ہی بے عزت ہوگا.[2]",
      "en": "She said, \"That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased.\"",
      "footnotesUr": "[1] جب امرأة العزیز نے دیکھا اس کی چال کامیاب رہی ہے اور عورتیں یوسف (عليه السلام) کے جلوہ حسن آراء سے مد ہوش ہوگئیں تو کہنے لگی، کہ اس کی ایک جھلک سے تمہارا یہ حال ہو گیا ہے تو کیا تم اب بھی مجھے اس کی محبت میں گرفتار ہونے پر طعنہ زنی کروگی؟ یہی وہ غلام ہے جس کے بارے میں تم مجھے ملامت کرتی ہو۔\n[2] عورتوں کی مد ہوشی دیکھ کر اس کو مزید حوصلہ ہو گیا اور شرم و حیا کے سارے حجاب دور کر کے اس نے اپنے برے ارادے کا ایک مرتبہ پھر اظہار کیا۔",
