      "number": 34,
      "arFull": "فَاسْتَجَابَ لَهٗ رَبُّهٗ فَصَرَفَ عَنْهُ كَیْدَهُنَّ ؕ اِنَّهٗ هُوَ السَّمِیْعُ الْعَلِیْمُ ۟",
