      "ur": "ان دو قیدیوں میں سے جو رہا ہوا تھا اسے مدت کے بعد یاد آگیا اور کہنے لگامیں تمہیں اس کی تعبیر بتلا دوں گا مجھے جانے کی اجازت دیجئے.[1]",
      "en": "But the one who was freed and remembered after a time said, \"I will inform you of its interpretation, so send me forth.\"",
      "footnotesUr": "[1] یہ قید کے دو ساتھیوں میں سے ایک نجات پانے والا تھا، جسے حضرت یوسف (عليه السلام) نے کہا تھا کہ اپنے آقا سے میرا ذکر کرنا، تاکہ میری رہائی کی صورت بن سکے۔ اسے اچانک یاد آیا اور اس نے کہا کہ مجھے مہلت دو میں تمہیں آ کر اس کی تعبیر بتلاتا ہوں، چنانچہ وہ نکل کر سیدھا یوسف (عليه السلام) کے پاس پہنچا اور خواب کی تفصیل بتا کر اس کی تعبیر کی بابت پوچھا۔",
