      "ur": "پس اگر تم اسے لے کر پاس نہ آئے تو میری طرف سے تمہیں کوئی ناپ بھی نہ ملے گا بلکہ تم میرے قریب بھی نہ پھٹکنا.[1]",
      "en": "But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me.\"",
      "footnotesUr": "[1] ترغیب کے ساتھ یہ دھمکی ہے کہ اگر گیارہویں بھائی کو ساتھ نہ لائے تو نہ تمہیں غلہ ملے گا نہ میری طرف سے اس خاطر مدارت کا اہتمام ہوگا۔",
