      "arFull": "قَالُوْا یٰۤاَیُّهَا الْعَزِیْزُ اِنَّ لَهٗۤ اَبًا شَیْخًا كَبِیْرًا فَخُذْ اَحَدَنَا مَكَانَهٗ ۚ اِنَّا نَرٰىكَ مِنَ الْمُحْسِنِیْنَ ۟",
      "ur": "انہوں نے کہا کہ اے عزیز مصر[1] ! اس کے والد بہت بڑی عمر کے بالکل بوڑھے شخص ہیں۔ آپ اس کے بدلے ہم میں سے کسی کو لے لیجئے۔ ہم دیکھتے ہیں کہ آپ بڑے نیک نفس ہیں.[2]",
      "en": "They said, \"O ʿAzeez,[611] indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good.\"",
      "footnotesUr": "[1] حضرت یوسف کو عزیز مصر اس لئے کہا کہ اس وقت اصل اختیارات حضرت یوسف (عليه السلام) کے ہی پاس تھے، بادشاہ صرف برائے نام فرمانروائے مصر تھا۔\n[2] باپ تو یقینا بوڑھے ہی تھے، لیکن یہاں ان کا اصل مقصد بنیامین کو چھڑانا تھا۔ ان کے ذہن میں وہی یوسف (عليه السلام) والی بات تھی کہ کہیں ہمیں پھر دوبارہ بنیامین کے بغیر باپ کے پاس جانا پڑے اور باپ ہم سے کہیں کہ تم نے میرے بنیامین کو بھی یوسف (عليه السلام) کی طرح کہیں گم کر دیا۔ اس لئے یوسف (عليه السلام) کے احسانات کے حوالے سے یہ بات کی کہ شاید وہ یہ احسان بھی کر دیں کہ بنیامین کو چھوڑ دیں اور اس کی جگہ کسی اور بھائی کو رکھ لیں۔",
