      "arFull": "قَالَ مَعَاذَ اللّٰهِ اَنْ نَّاْخُذَ اِلَّا مَنْ وَّجَدْنَا مَتَاعَنَا عِنْدَهٗۤ ۙ اِنَّاۤ اِذًا لَّظٰلِمُوْنَ ۟۠",
      "ur": "یوسف (علیہ السلام) نے کہا ہم نے جس کے پاس اپنی چیز پائی ہے اس کے سوا دوسرے کی گرفتاری کرنے سے اللہ کی پناه چاہتے ہیں، ایسا کرنے سے تو ہم یقیناً ناانصافی کرنے والے ہو جائیں گے.[1]",
