      "arFull": "قَالُوْا تَاللّٰهِ تَفْتَؤُا تَذْكُرُ یُوْسُفَ حَتّٰی تَكُوْنَ حَرَضًا اَوْ تَكُوْنَ مِنَ الْهٰلِكِیْنَ ۟",
      "ur": "بیٹوں نے کہا واللہ! آپ ہمیشہ یوسف کی یاد ہی میں لگے رہیں گے یہاں تک کہ گھل جائیں یا ختم ہی ہو جائیں.[1]",
