      "arFull": "قَالَ اِنَّمَاۤ اَشْكُوْا بَثِّیْ وَحُزْنِیْۤ اِلَی اللّٰهِ وَاَعْلَمُ مِنَ اللّٰهِ مَا لَا تَعْلَمُوْنَ ۟",
