      "arFull": "یٰبَنِیَّ اذْهَبُوْا فَتَحَسَّسُوْا مِنْ یُّوْسُفَ وَاَخِیْهِ وَلَا تَایْـَٔسُوْا مِنْ رَّوْحِ اللّٰهِ ؕ اِنَّهٗ لَا یَایْـَٔسُ مِنْ رَّوْحِ اللّٰهِ اِلَّا الْقَوْمُ الْكٰفِرُوْنَ ۟",
      "ur": "میرے پیارے بچو! تم جاؤ اور یوسف (علیہ السلام) کی اور اس کے بھائی کی پوری طرح تلاش کرو[1] اور اللہ کی رحمت سے ناامید نہ ہو۔ یقیناً رب کی رحمت سے ناامید وہی ہوتے ہیں جو کافر ہوتے ہیں.[2]",
      "en": "O my sons, go and find out about Joseph and his brother and despair not of relief from Allāh. Indeed, no one despairs of relief from Allāh except the disbelieving people.\"",
      "footnotesUr": "[1] چنانچہ اس یقین سے سرشار ہو کر انہوں نے اپنے بیٹوں کو یہ حکم دیا۔\n[2] جس طرح دوسرے مقام پر اللہ تعالٰی نے فرمایا «قَالَ وَمَنْ يَّقْنَطُ مِنْ رَّحْمَةِ رَبِّهٖٓ اِلَّا الضَّاۗلُّوْنَ» (الحجر:56) ”گمراہ لوگ ہی اللہ کی رحمت سے نا امید ہوتے ہیں“ اس کا مطلب یہ ہے کہ اہل ایمان کو سخت حالات میں بھی صبر و رضا کا اور اللہ کی رحمت واسعہ کی امید کا دامن نہیں چھوڑنا چاہیئے۔",
      "footnotesEn": null,
