      "arFull": "قَالَ سَوْفَ اَسْتَغْفِرُ لَكُمْ رَبِّیْ ؕ اِنَّهٗ هُوَ الْغَفُوْرُ الرَّحِیْمُ ۟",
      "ur": "کہا اچھا میں جلد ہی تمہارے لئے اپنے پروردگار سے بخشش مانگوں گا[1] ، وه بہت بڑا بخشنے واﻻ اور نہایت مہربانی کرنے وﻻ ہے.",
      "en": "He said, \"I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful.\"",
      "footnotesUr": "[1] فی الفور مغفرت کی دعا کرنے کی بجائے دعا کرنے کا وعدہ فرمایا، مقصد یہ تھا کہ رات کے پچھلے پہر میں، جو اللہ کے خاص بندوں کا اللہ کی عبادت کرنے کا خاص وقت ہوتا ہے، اللہ سے ان کی مغفرت کی دعا کروں گا، دوسری بات یہ کہ بھائیوں کی زیادتی یوسف (عليه السلام) پر تھی، ان سے مشورہ لینا ضروری تھا اس لئے انہوں نے تاخیر کی اور فوراً مغفرت کی دعا نہیں کی۔",
      "footnotesEn": null,
