      "arFull": "وَمَا تَسْـَٔلُهُمْ عَلَیْهِ مِنْ اَجْرٍ ؕ اِنْ هُوَ اِلَّا ذِكْرٌ لِّلْعٰلَمِیْنَ ۟۠",
